## **RECOMMENDED SECRETS MANAGEMENT ARCHITECTURE**

### **Option 1: AWS Secrets Manager (Recommended for AWS environments)**

**package.json dependencies:**
```json
{
  "dependencies": {
    "@aws-sdk/client-secrets-manager": "^3.0.0"
  }
}
```

**Implementation:**
```javascript
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
      // Use instance profile or IAM roles, not hardcoded credentials
    });
    this.cache = new Map();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTimeout) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      let secret;
      if ('SecretString' in response) {
        secret = JSON.parse(response.SecretString);
      } else {
        secret = Buffer.from(response.SecretBinary, 'base64').toString('utf8');
      }

      // Cache with timestamp
      this.cache.set(secretName, { value: secret, timestamp: Date.now() });

      return secret;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error.message);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  // Warm up cache on startup
  async warmup(...secretNames) {
    await Promise.all(secretNames.map(name => this.getSecret(name)));
  }
}

// Singleton instance
const secretsManager = new SecretsManager();

// Example usage in app initialization
async function initializeApp() {
  try {
    const dbSecrets = await secretsManager.getSecret('prod/database');
    const stripeSecrets = await secretsManager.getSecret('prod/stripe');
    const apiSecrets = await secretsManager.getSecret('prod/api-keys');

    // Validate required secrets exist
    if (!dbSecrets.url || !stripeSecrets.secret_key) {
      throw new Error('Required secrets missing');
    }

    return {
      databaseUrl: dbSecrets.url,
      stripeSecretKey: stripeSecrets.secret_key,
      anthropicApiKey: apiSecrets.anthropic_key
    };
  } catch (error) {
    console.error('Failed to initialize application:', error);
    process.exit(1);
  }
}

module.exports = { secretsManager, initializeApp };
```

