#!/usr/bin/env node

/**
 * Credential Rotation Report Generator
 * Extracts secrets from .env files and creates redacted previews for tracking
 */

const fs = require('fs');
const path = require('path');

// Redact a value to show only first 4 and last 4 characters
function redactValue(value) {
  if (!value || value.length <= 8) {
    return '********'; // Too short to redact safely
  }
  const first = value.substring(0, 4);
  const last = value.substring(value.length - 4);
  const masked = '*'.repeat(value.length - 8);
  return `${first}${masked}${last}`;
}

// Parse .env file
function parseEnvFile(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  const lines = content.split('\n');
  const secrets = [];

  for (const line of lines) {
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    // Parse KEY=VALUE format
    const equalsIndex = trimmed.indexOf('=');
    if (equalsIndex === -1) continue;

    const key = trimmed.substring(0, equalsIndex).trim();
    const value = trimmed.substring(equalsIndex + 1).trim();

    // Only include credentials (not simple config values)
    if (key.includes('SECRET') || key.includes('KEY') || key.includes('TOKEN') || key.includes('PASSWORD')) {
      secrets.push({
        variableName: key,
        redactedValue: redactValue(value),
        fullLength: value.length,
        category: categorizeSecret(key),
        priority: assessPriority(key, value)
      });
    }
  }

  return secrets;
}

// Categorize the secret type
function categorizeSecret(key) {
  if (key.includes('DATABASE') || key.includes('DB')) return 'Database';
  if (key.includes('AWS')) return 'Cloud Infrastructure';
  if (key.includes('STRIPE')) return 'Payment Processing';
  if (key.includes('ANTHROPIC') || key.includes('AI')) return 'AI/ML Services';
  if (key.includes('JWT') || key.includes('AUTH')) return 'Authentication';
  if (key.includes('LOG') || key.includes('MONITOR')) return 'Logging/Monitoring';
  return 'Other';
}

// Assess rotation priority based on secret type
function assessPriority(key, value) {
  // Critical priority for production credentials
  if (key.includes('LIVE') || key.includes('PROD')) return 'CRITICAL';
  if (key.includes('ADMIN') || key.includes('ROOT')) return 'CRITICAL';

  // High priority for credentials
  if (key.includes('STRIPE') || key.includes('AWS_SECRET')) return 'HIGH';
  if (key.includes('DATABASE') || key.includes('DB')) return 'HIGH';

  // Medium priority for API keys
  if (key.includes('API_KEY') || key.includes('TOKEN')) return 'MEDIUM';

  return 'LOW';
}

// Generate CSV report for spreadsheet import
function generateCSVReport(secrets) {
  const headers = [
    'Variable Name',
    'Category',
    'Priority',
    'Redacted Preview',
    'Character Count',
    'Rotation Status',
    'Rotated By',
    'Rotation Date',
    'Notes'
  ];

  const rows = secrets.map(secret => [
    secret.variableName,
    secret.category,
    secret.priority,
    secret.redactedValue,
    secret.fullLength,
    'PENDING', // Default status
    '',
    '',
    ''
  ]);

  return [headers, ...rows]
    .map(row => row.map(cell => `"${cell}"`).join(','))
    .join('\n');
}

// Generate human-readable report
function generateConsoleReport(secrets) {
  console.log('\n╔════════════════════════════════════════════════════════════════╗');
  console.log('║           CREDENTIAL ROTATION TRACKING REPORT                  ║');
  console.log('╚════════════════════════════════════════════════════════════════╝\n');

  console.log('┌──────────────┬──────────────────────┬────────────┬─────────────────────┬────────┐');
  console.log('│ Variable     │ Category             │ Priority   │ Redacted Preview    │ Length │');
  console.log('├──────────────┼──────────────────────┼────────────┼─────────────────────┼────────┤');

  for (const secret of secrets) {
    const variable = secret.variableName.padEnd(12);
    const category = secret.category.padEnd(20);
    const priority = secret.priority.padEnd(10);
    const redacted = secret.redacted.padEnd(19);
    const length = String(secret.fullLength).padEnd(6);

    const color = secret.priority === 'CRITICAL' ? '🔴' :
                  secret.priority === 'HIGH' ? '🟠' :
                  secret.priority === 'MEDIUM' ? '🟡' : '⚪';

    console.log(`│ ${variable} │ ${category} │ ${priority} │ ${redacted} │ ${length} │ ${color}│`);
  }

  console.log('└──────────────┴──────────────────────┴────────────┴─────────────────────┴────────┘');
  console.log(`\n📊 Total credentials requiring rotation: ${secrets.length}`);
  console.log(`🔴 Critical: ${secrets.filter(s => s.priority === 'CRITICAL').length}`);
  console.log(`🟠 High: ${secrets.filter(s => s.priority === 'HIGH').length}`);
  console.log(`🟡 Medium: ${secrets.filter(s => s.priority === 'MEDIUM').length}\n`);
}

// Main execution
const envFile = '.env.test';

if (!fs.existsSync(envFile)) {
  console.error(`Error: ${envFile} not found`);
  process.exit(1);
}

try {
  const secrets = parseEnvFile(envFile);

  // Generate console report
  generateConsoleReport(secrets);

  // Generate CSV for spreadsheet
  const csvReport = generateCSVReport(secrets);
  const csvFile = 'credential-rotation-report.csv';

  fs.writeFileSync(csvFile, csvReport);

  console.log(`📄 CSV report generated: ${csvFile}`);
  console.log('   Import this file into your spreadsheet application.\n');

  // Generate JSON for automation
  const jsonReport = JSON.stringify(secrets, null, 2);
  const jsonFile = 'credential-rotation-report.json';

  fs.writeFileSync(jsonFile, jsonReport);

  console.log(`📋 JSON report generated: ${jsonFile}`);
  console.log('   Use this for automation or API integration.\n');

  console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
  console.log('⚠️  SECURITY REMINDER:');
  console.log('   1. Immediately rotate all CRITICAL priority credentials');
  console.log('   2. Rotate HIGH priority credentials within 24 hours');
  console.log('   3. Update all applications/services using these credentials');
  console.log('   4. Delete old credentials from all systems after rotation');
  console.log('   5. Document rotation completion in the tracking spreadsheet');
  console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n');

} catch (error) {
  console.error('Error processing secrets:', error.message);
  process.exit(1);
}

