### **Option 1: AWS Secrets Manager (Recommended for AWS Workloads)**

```javascript
// config/secrets.js
const AWS = require('aws-sdk');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// Initialize with IAM role or credentials from EC2 instance metadata
const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

let secretsCache = {};
let cacheExpiry = null;

/**
 * Retrieve secret from AWS Secrets Manager with caching
 */
async function getSecret(secretName, forceRefresh = false) {
  // Check cache first (5 minute TTL)
  if (!forceRefresh && secretsCache[secretName] && cacheExpiry && Date.now() < cacheExpiry) {
    return secretsCache[secretName];
  }

  try {
    const response = await client.send(
      new GetSecretValueCommand({ SecretId: secretName })
    );

    let secret;
    if (response.SecretString) {
      secret = JSON.parse(response.SecretString);
    } else {
      secret = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
    }

    // Update cache
    secretsCache[secretName] = secret;
    cacheExpiry = Date.now() + (5 * 60 * 1000); // 5 minutes

    return secret;
  } catch (error) {
    if (error.name === 'ResourceNotFoundException') {
      throw new Error(`Secret not found: ${secretName}`);
    } else if (error.name === 'DecryptionFailureException') {
      throw new Error(`Decryption failed for: ${secretName}`);
    } else if (error.name === 'InvalidRequestException') {
      throw new Error(`Invalid request for: ${secretName}`);
    } else {
      console.error('Error retrieving secret:', error);
      throw error;
    }
  }
}

/**
 * Load all required secrets at startup
 */
async function loadAllSecrets() {
  try {
    console.log('Loading secrets from AWS Secrets Manager...');

    const secrets = {
      database: await getSecret('prod/app/database'),
      aws: await getSecret('prod/app/aws-credentials'),
      stripe: await getSecret('prod/app/stripe'),
      anthropic: await getSecret('prod/app/anthropic'),
      logfire: await getSecret('prod/app/logfire')
    };

    console.log('✅ Secrets loaded successfully');
    return secrets;
  } catch (error) {
    console.error('❌ Failed to load secrets:', error.message);
    throw error;
  }
}

module.exports = { getSecret, loadAllSecrets };
