### **Option 5: Hybrid Solution - Auto-detect Environment**

```javascript
// config/secrets-loader.js
const { loadSecrets: loadFromAws } = require('./aws-secrets');
const { getSecrets: loadFromEnv } = require('./env-secrets');
const { loadSecrets: loadFromVault } = require('./vault-secrets');

function getSecretsProvider() {
  const provider = process.env.SECRETS_PROVIDER || 'auto';
  const env = process.env.NODE_ENV || 'development';

  if (provider === 'aws') {
    return loadFromAws;
  } else if (provider === 'vault') {
    return loadFromVault;
  } else if (provider === 'env') {
    return loadFromEnv;
  } else if (provider === 'auto') {
    // Auto-detect based on environment
    if (env === 'production') {
      // Check if running in AWS
      if (process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION) {
        return loadFromAws;
      }
      // Check if running in Kubernetes with Vault sidecar
      if (process.env.VAULT_ADDR && process.env.VAULT_TOKEN) {
        return loadFromVault;
      }
    }
    // Default to env for development/staging
    return loadFromEnv;
  }

  throw new Error(`Unknown secrets provider: ${provider}`);
}

async function loadSecrets() {
  const provider = getSecretsProvider();
  console.log(`Loading secrets using provider: ${provider.name || 'detected'}`);

  const secrets = await provider();

  // Validate secrets structure
  if (!secrets.database || !secrets.database.url) {
    throw new Error('Invalid secrets: missing database.url');
  }

  return secrets;
}

module.exports = { loadSecrets, getSecretsProvider };
