```javascript
// Install dependencies
// npm install @aws-sdk/client-secrets-manager

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// Initialize Secrets Manager client
const secretsClient = new SecretsManagerClient({
  region: process.env.AWS_REGION || 'us-east-1'
});

// Cache secrets in memory (with TTL)
let secretsCache = null;
let cacheExpiry = 0;
const CACHE_TTL = 5 * 60 * 1000; // 5 minutes

async function getSecret(secretName) {
  // Check cache first
  if (secretsCache && Date.now() < cacheExpiry && secretsCache[secretName]) {
    return secretsCache[secretName];
  }

  try {
    const command = new GetSecretValueCommand({
      SecretId: secretName,
      VersionStage: 'AWSCURRENT'
    });

    const response = await secretsClient.send(command);
    const secret = JSON.parse(response.SecretString);

    // Update cache
    if (!secretsCache || Date.now() >= cacheExpiry) {
      secretsCache = {};
      cacheExpiry = Date.now() + CACHE_TTL;
    }
    secretsCache[secretName] = secret;

    return secret;
  } catch (error) {
    console.error(`Error retrieving secret ${secretName}:`, error.message);
    throw new Error('Failed to retrieve configuration');
  }
}

// Usage in app initialization
async function initializeApp() {
  try {
    const dbSecrets = await getSecret('prod/myapp/database');
    const stripeSecrets = await getSecret('prod/myapp/stripe');
    const apiSecrets = await getSecret('prod/myapp/api-keys');

    // Use secrets
    process.env.DATABASE_URL = dbSecrets.connection_string;
    process.env.STRIPE_SECRET_KEY = stripeSecrets.secret_key;
    process.env.ANTHROPIC_API_KEY = apiSecrets.anthropic_key;

    // Start server with loaded secrets
    require('./app');
  } catch (error) {
    console.error('Failed to initialize application:', error);
    process.exit(1);
  }
}

