const { SecretsManagerClient } = require('@aws-sdk/client-secrets-manager');
const { execSync } = require('child_process');
const crypto = require('crypto');

const client = new SecretsManagerClient({ region: 'us-east-1' });

async function rotateDatabaseCredential() {
  // Generate new password (never log it)
  const newPassword = crypto.randomBytes(32).toString('base64');

  // Execute rotation via SQL (password passed as parameter, never in logs)
  const sql = `ALTER USER admin WITH PASSWORD '${newPassword}';`;

