  });

  // Store new secret in Secrets Manager
  await client.send({
    SecretId: 'prod/myapp/database',
    SecretString: JSON.stringify({
      connection_string: `postgresql://admin:${newPassword}@host:5432/db`,
      username: 'admin'
    })
  });

  console.log('✓ Database credential rotated (value not shown)');
}

async function rotateStripeKey() {
