### Option 2: AWS Secrets Manager (Production) ⭐ RECOMMENDED

```javascript
// ✅ PRODUCTION-GRADE SECRETS MANAGEMENT
const AWS = require('aws-sdk');
const express = require('express');

class SecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-west-2'
    });
    this.cache = new Map();
    this.cacheTimeout = 300000; // 5 minutes
  }

  async getSecret(secretName, useCache = true) {
    // Check cache first
    if (useCache && this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTimeout) {
        return cached.value;
      }
    }

    try {
      const data = await this.client.getSecretValue({
        SecretId: secretName
      }).promise();

      let secret;
      if (data.SecretString) {
        secret = JSON.parse(data.SecretString);
      } else {
        secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error.message);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  // Reload on secret rotation
  async invalidateCache(secretName) {
    this.cache.delete(secretName);
  }
}

// Initialize secrets manager
const secretsManager = new SecretsManager();

// Load secrets at startup
async function loadSecrets() {
  try {
    const dbSecret = await secretsManager.getSecret('prod/database/credentials');
    const stripeSecret = await secretsManager.getSecret('prod/stripe/keys');
    const apiKeys = await secretsManager.getSecret('prod/api/keys');

    return {
      databaseUrl: `postgresql://${dbSecret.username}:${dbSecret.password}@${dbSecret.host}:${dbSecret.port}/${dbSecret.dbname}`,
      jwtSecret: apiKeys.jwt,
      stripeSecretKey: stripeSecret.secret_key,
      awsKeyId: apiKeys.aws_access_key_id,
      awsSecret: apiKeys.aws_secret_access_key
    };
  } catch (error) {
    console.error('Failed to load secrets:', error);
    process.exit(1);
  }
}

// Initialize app with secrets
async function initializeApp() {
  const secrets = await loadSecrets();

  const app = express();

  // Use secrets - never log them!
  app.locals.secrets = secrets;

  // Database connection with secrets
  const { Pool } = require('pg');
  const pool = new Pool({
    connectionString: secrets.databaseUrl,
    ssl: { rejectUnauthorized: true } // Required for production
  });

  app.get('/users', async (req, res) => {
    try {
      const result = await pool.query('SELECT id, name, email FROM users LIMIT 100');
      res.json(result.rows);
    } catch (error) {
      console.error('Database error:', error.message);
      res.status(500).json({ error: 'Database error' });
    }
  });

  return app;
}

// Start server
initializeApp().then(app => {
  app.listen(3000, () => {
    console.log('Server started with secrets loaded from AWS Secrets Manager');
  });
});

module.exports = initializeApp;
