## 🛡️ COMPREHENSIVE SECURITY HARDENING

### Complete Secure Implementation:

```javascript
// ✅ COMPLETE SECURE app.js
require('dotenv').config(); // ONLY for development

const AWS = require('aws-sdk');
const express = require('express');
const app = express();

// Secrets Manager configuration
const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-west-2'
});

// Environment-aware secret loading
async function getSecret(secretName) {
  // Development: use .env (NEVER commit)
  if (process.env.NODE_ENV === 'development') {
    const envVar = secretName.toUpperCase().replace(/-/g, '_');
    return process.env[envVar];
  }

  // Production: use Secrets Manager
  try {
    const data = await secretsManager.getSecretValue({
      SecretId: `prod/${secretName}`
    }).promise();

    return JSON.parse(data.SecretString);
  } catch (error) {
    console.error(`Failed to load secret ${secretName}:`, error.message);
    throw error;
  }
}

// Secret validation on startup
async function validateSecrets() {
  const required = {
    database: await getSecret('database'),
    jwt: await getSecret('jwt'),
    stripe: await getSecret('stripe')
  };

  // Validate structure
  if (!required.database?.url) {
    throw new Error('Invalid database secret format');
  }

  return required;
}

// Audit logging for secret access
function logSecretAccess(secretName, user = 'system') {
  console.warn(`[AUDIT] Secret accessed: ${secretName} by ${user}`, {
    timestamp: new Date().toISOString(),
    secretName,
    user,
    // NEVER log the actual secret value!
  });
}

// Startup with secrets
async function startServer() {
  try {
    console.log('Loading secrets...');
    const secrets = await validateSecrets();
    console.log('✓ Secrets loaded successfully');

    // Configure app with secrets
    app.set('dbUrl', secrets.database.url);
    app.set('jwtSecret', secrets.jwt.secret);

    const server = app.listen(process.env.PORT || 3000, () => {
      console.log(`✓ Server running on port ${process.env.PORT || 3000}`);
    });

    // Handle secret rotation
    const rotationInterval = parseInt(process.env.SECRET_ROTATION_CHECK || '3600000');
    setInterval(async () => {
      try {
        logSecretAccess('rotation-check');
        const newSecrets = await validateSecrets();
        app.set('jwtSecret', newSecrets.jwt.secret);
        console.log('✓ Secrets rotated');
      } catch (error) {
        console.error('Secret rotation failed:', error.message);
      }
    }, rotationInterval);

    return server;
  } catch (error) {
    console.error('Failed to start server:', error.message);
    process.exit(1);
  }
}

// Prevent dumping secrets on crashes
process.on('unhandledRejection', (error) => {
  console.error('Unhandled rejection:', error.message);
  // Don't log full error object in production!
});

startServer();

module.exports = app;
```

