### 7. **Add Pre-commit Hook to Block Secrets**

```javascript
// scripts/check-secrets.js
const fs = require('fs');
const path = require('path');

function checkForSecrets(dir = '.') {
  const disallowedFiles = ['.env', '.env.local', '.env.prod', '.env.test'];
  const allowedPatterns = [/^\.(env\.example|gitignore)$/];

  const files = fs.readdirSync(dir, { withFileTypes: true });

  for (const file of files) {
    if (file.isFile()) {
      const isDisallowed = disallowedFiles.includes(file.name);
      const isAllowed = allowedPatterns.some(p => p.test(file.name));

      if (isDisallowed && !isAllowed) {
        console.error(`❌ Found disallowed file: ${file.name}`);
        console.error('   This file should not be committed to version control.');
        return false;
      }
    }
  }

  return true;
}

if (!checkForSecrets()) {
  console.error('\n❌ Pre-commit check failed: Secrets found in workspace');
  process.exit(1);
}

console.log('✅ No secret files found');
```

