```javascript
// scan-secret-refs.js
const fs = require('fs');
const path = require('path');

const SECRET_PATTERNS = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID', 
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'DREDD_API_KEY',
  'LOGFIRE_TOKEN',
];

function scanDirectory(dir) {
  const results = [];

  function scan(currentDir) {
    const files = fs.readdirSync(currentDir);

    for (const file of files) {
      const filepath = path.join(currentDir, file);
      const stat = fs.statSync(filepath);

      if (stat.isDirectory() && !file.startsWith('.') && file !== 'node_modules') {
        scan(filepath);
      } else if (file.match(/\.(js|json|env|yml|yaml|md)$/)) {
        const content = fs.readFileSync(filepath, 'utf8');
        const matches = [];

        for (const pattern of SECRET_PATTERNS) {
          const regex = new RegExp(pattern, 'g');
          let match;
          while ((match = regex.exec(content)) !== null) {
            matches.push({
              pattern,
              line: content.substring(0, match.index).split('\n').length,
            });
          }
        }

        if (matches.length > 0) {
          results.push({
            file: filepath,
            matches: matches.length,
            patterns: [...new Set(matches.map(m => m.pattern))],
          });
        }
      }
    }
  }

  scan(dir);
  return results;
}

console.log('\n🔍 Scanning for secret variable references...\n');
const findings = scanDirectory(process.cwd());

if (findings.length === 0) {
  console.log('✅ No secret references found');
} else {
  console.log('Found secret references in:\n');
  for (const finding of findings) {
    console.log(`${finding.file}:`);
    console.log(`  Patterns: ${finding.patterns.join(', ')}`);
    console.log(`  Occurrences: ${finding.matches}\n`);
  }
}
```

