### Option 2: AWS Secrets Manager (Production-Grade)

```javascript
// Install: npm install @aws-sdk/client-secrets-manager
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// secrets.js - Secure secrets loader
class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName, forceRefresh = false) {
    // Check cache first
    if (!forceRefresh && this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        return cached.value;
      }
    }

    try {
      const command = new GetSecretValueCommand({
        SecretId: secretName
      });

      const response = await this.client.send(command);
      const secret = response.SecretString 
        ? JSON.parse(response.SecretString)
        : response.SecretBinary;

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      console.error(`Error fetching secret ${secretName}:`, error.message);
      throw new Error(`Failed to load secret: ${secretName}`);
    }
  }

  async loadAllSecrets() {
    const secretNames = [
      `${process.env.APP_NAME}/production/database`,
      `${process.env.APP_NAME}/production/aws`,
      `${process.env.APP_NAME}/production/api-keys`
    ];

    const secrets = {};
    for (const name of secretNames) {
      try {
        const secret = await this.getSecret(name);
        Object.assign(secrets, secret);
      } catch (error) {
        console.error(`Failed to load ${name}:`, error.message);
      }
    }

    return secrets;
  }
}

module.exports = SecretsManager;
```

