// vault.js - HashiCorp Vault integration
const axios = require('axios');

class VaultClient {
  constructor({ url, roleId, secretId, mount = 'secret' }) {
    this.url = url;
    this.mount = mount;
    this.token = null;
    this.roleId = roleId;
    this.secretId = secretId;
  }

  async authenticate() {
    try {
      const response = await axios.post(
        `${this.url}/v1/auth/approle/login`,
        {
          role_id: this.roleId,
          secret_id: this.secretId
        }
      );

      this.token = response.data.auth.client_token;
      this.tokenTTL = response.data.auth.lease_duration * 1000;
      this.tokenExpiry = Date.now() + this.tokenTTL;

      return true;
    } catch (error) {
      console.error('Vault authentication failed:', error.message);
      throw error;
    }
  }

  async getSecret(path) {
    // Refresh token if expired
    if (!this.token || Date.now() > this.tokenExpiry) {
      await this.authenticate();
    }

    try {
      const response = await axios.get(
        `${this.url}/v1/${this.mount}/data/${path}`,
        {
          headers: {
            'X-Vault-Token': this.token
          }
        }
      );

      return response.data.data.data;
    } catch (error) {
      console.error(`Error fetching secret from Vault at ${path}:`, error.message);
      throw error;
    }
  }
}

module.exports = VaultClient;
