      // Parse if JSON string
      let secret = data.SecretString;
      if (secret.startsWith('{')) {
        secret = JSON.parse(secret);
      }

      // Cache the result
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      console.error(`❌ Failed to fetch secret ${secretName}:`, error.message);
      throw new Error(`Secret fetch failed: ${secretName}`);
    }
  }

  async getAllSecrets() {
    const secrets = {};

    try {
      secrets.database = await this.getSecret('production/database');
      secrets.aws = await this.getSecret('production/aws');
      secrets.stripe = await this.getSecret('production/stripe');
      secrets.anthropic = await this.getSecret('production/anthropic');

      return secrets;
    } catch (error) {
      throw error;
    }
  }
}

module.exports = new SecretsManager();
