const secretsManager = require('./secrets-manager');
const dotenv = require('dotenv');

class SecretsLoader {
  constructor() {
    this.secrets = {};
  }

  async load() {
    const environment = process.env.NODE_ENV || 'development';
    console.log(`🔧 Loading secrets for ${environment}...`);

    if (environment === 'production') {
      // Use AWS Secrets Manager in production
      await this.loadFromSecretsManager();
    } else if (environment === 'test') {
      // Use .env.test for testing
      dotenv.config({ path: '.env.test' });
      this.loadFromProcessEnv();
    } else {
      // Use .env for development
      dotenv.config();
      this.loadFromProcessEnv();
    }

    this.validate();
    console.log('✅ All secrets loaded and validated');

    return this.secrets;
  }

  async loadFromSecretsManager() {
    this.secrets = await secretsManager.getAllSecrets();
  }

  loadFromProcessEnv() {
    this.secrets = {
      database: {
        url: process.env.DATABASE_URL
      },
      aws: {
        accessKeyId: process.env.AWS_ACCESS_KEY_ID,
        secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
        region: process.env.AWS_REGION || 'us-east-1'
      },
      stripe: {
        secretKey: process.env.STRIPE_SECRET_KEY
      },
      anthropic: {
        apiKey: process.env.ANTHROPIC_API_KEY
      },
      logfire: {
        token: process.env.LOGFIRE_TOKEN
      }
    };
  }

  validate() {
    const required = ['database.url', 'aws.accessKeyId', 'aws.secretAccessKey'];
    const missing = [];

    for (const path of required) {
      const value = this.getNestedValue(this.secrets, path);
      if (!value) {
        missing.push(path);
      }
    }

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }
  }

  getNestedValue(obj, path) {
    return path.split('.').reduce((acc, part) => acc?.[part], obj);
  }

  get(path) {
    return this.getNestedValue(this.secrets, path);
  }
}

module.exports = new SecretsLoader();
