// config/secrets.js - Universal secrets loader
const AWS = require('aws-sdk');
const dotenv = require('dotenv');
const Vault = require('node-vault');

class UniversalSecretsLoader {
  constructor() {
    this.provider = process.env.SECRETS_PROVIDER || 'env';
    this.cache = new Map();
  }

  async load() {
    console.log(`🔐 Loading secrets from provider: ${this.provider}`);

    switch (this.provider) {
      case 'aws-secrets-manager':
        return await this.loadFromAWS();
      case 'hashicorp-vault':
        return await this.loadFromVault();
      case 'env':
      default:
        return await this.loadFromEnv();
    }
  }

  async loadFromAWS() {
    const client = new AWS.SecretsManager({
      region: process.env.AWS_REGION
    });

    const secrets = await Promise.all([
      this.getAWSSecret(client, 'production/database'),
      this.getAWSSecret(client, 'production/aws'),
      this.getAWSSecret(client, 'production/stripe'),
    ]);

    return Object.assign({}, ...secrets);
  }

  async getAWSSecret(client, secretId) {
    const data = await client.getSecretValue({ SecretId: secretId }).promise();
    const key = secretId.split('/').pop();
    return { [key]: JSON.parse(data.SecretString) };
  }

  async loadFromVault() {
    const vault = Vault({
      endpoint: process.env.VAULT_ADDR,
      token: process.env.VAULT_TOKEN
    });

    const secrets = {};
    const paths = ['secret/database', 'secret/aws', 'secret/stripe'];

    for (const path of paths) {
      const result = await vault.read(path);
      const key = path.split('/').pop();
      secrets[key] = result.data;
    }

    return secrets;
  }

  async loadFromEnv() {
    const envPath = process.env.NODE_ENV === 'test' 
      ? '.env.test' 
      : '.env';

    dotenv.config({ path: envPath });

    return {
      database: {
        url: process.env.DATABASE_URL
      },
      aws: {
        accessKeyId: process.env.AWS_ACCESS_KEY_ID,
        secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY
      },
      stripe: {
        secretKey: process.env.STRIPE_SECRET_KEY
      },
      anthropic: {
        apiKey: process.env.ANTHROPIC_API_KEY
      }
    };
  }
}

module.exports = new UniversalSecretsLoader();
