#!/usr/bin/env node

/**
 * Secrets Audit Tool
 * Scans codebase for hardcoded secrets and sensitive data
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

// Patterns that might indicate secrets
const SECRET_PATTERNS = [
  /password\s*[:=]\s*['"]([^'"]{8,})['"]/gi,
  /secret\s*[:=]\s*['"]([^'"]{10,})['"]/gi,
  /api[_-]?key\s*[:=]\s*['"]([^'"]{15,})['"]/gi,
  /access[_-]?key[_-]?id\s*[:=]\s*['"]([^'"]{15,})['"]/gi,
  /secret[_-]?access[_-]?key\s*[:=]\s*['"]([^'"]{15,})['"]/gi,
  /private[_-]?key\s*[:=]\s*['"]([^'"]{20,})['"]/gi,
  /auth[_-]?token\s*[:=]\s*['"]([^'"]{20,})['"]/gi,
  /bearer\s+([a-zA-Z0-9_\-\.]+)$/gim,
  /sk_live_[a-zA-Z0-9]{20,}/g,
  /sk_test_[a-zA-Z0-9]{20,}/g,
  /AIza[a-zA-Z0-9_\-]{35}/g, // Google API key
  /AKIA[a-zA-Z0-9]{16}/g, // AWS access key
  /xoxb-[a-zA-Z0-9\-]+/g, // Slack bot token
  /postgresql?:\/\/[^@]+:[^@]+@/g, // DB connection strings
  /mongodb\+srv:\/\/[^@]+:[^@]+@/g, // MongoDB connection strings
  /redis:\/\/[^@]+:[^@]+@/g, // Redis connection strings
];

// Files to ignore
const IGNORE_PATTERNS = [
  /node_modules/,
  /\.git/,
  /coverage/,
  /dist/,
  /build/,
  /\.env\.example$/,
  /package-lock\.json/,
  /yarn\.lock/,
  /\.md$/,
  /\.txt$/,
];

// High-entropy strings that might be secrets
function calculateEntropy(str) {
  const frequencies = {};
  for (const char of str) {
    frequencies[char] = (frequencies[char] || 0) + 1;
  }

  let entropy = 0;
  const len = str.length;
  for (const char in frequencies) {
    const p = frequencies[char] / len;
    entropy -= p * Math.log2(p);
  }

  return entropy;
}

function findHighEntropyStrings(text, minLength = 20, threshold = 4.0) {
  const results = [];
  const strings = text.match(/["']([a-zA-Z0-9_\-\.]{20,})["']/g) || [];

  for (const str of strings) {
    const content = str.slice(1, -1);
    const entropy = calculateEntropy(content);

    if (entropy >= threshold && content.length >= minLength) {
      results.push({
        string: content,
        entropy: entropy.toFixed(2),
        trunc: content.substring(0, 8) + '...' + content.substring(content.length - 4)
      });
    }
  }

  return results;
}

function shouldIgnoreFile(filePath) {
  return IGNORE_PATTERNS.some(pattern => pattern.test(filePath));
}

function scanFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const findings = {
      file: filePath,
      secrets: [],
      highEntropy: []
    };

    // Check for secret patterns
    SECRET_PATTERNS.forEach((pattern, index) => {
      let match;
      while ((match = pattern.exec(content)) !== null) {
        findings.secrets.push({
          type: `Pattern ${index + 1}`,
          match: match[0],
          line: content.substring(0, match.index).split('\n').length,
          column: match.index - content.lastIndexOf('\n', match.index - 1)
        });
      }
    });

    // Check for high entropy strings
    const entropyMatches = findHighEntropyStrings(content);
    findings.highEntropy = entropyMatches;

    return findings;
  } catch (error) {
    return { file: filePath, error: error.message };
  }
}

function scanDirectory(dir, extensions = ['.js', '.json', '.env', '.ts', '.yml', '.yaml']) {
  const results = [];

  function walk(currentPath) {
    const items = fs.readdirSync(currentPath);

    for (const item of items) {
      const fullPath = path.join(currentPath, item);
      const stat = fs.statSync(fullPath);

      if (stat.isDirectory()) {
        if (!shouldIgnoreFile(fullPath)) {
          walk(fullPath);
        }
      } else if (stat.isFile()) {
        if (!shouldIgnoreFile(fullPath) && extensions.some(ext => item.endsWith(ext))) {
          console.log(`Scanning: ${fullPath}`);
          const result = scanFile(fullPath);
          if (result.secrets.length > 0 || result.highEntropy.length > 0) {
            results.push(result);
          }
        }
      }
    }
  }

  walk(dir);
  return results;
}

function generateReport(results) {
  let totalSecrets = 0;
  let totalHighEntropy = 0;

  console.log('\n' + '='.repeat(80));
  console.log('🔐 SECRETS AUDIT REPORT');
  console.log('='.repeat(80) + '\n');

  results.forEach(result => {
    if (result.error) {
      console.log(`❌ Error scanning ${result.file}: ${result.error}`);
      return;
    }

    if (result.secrets.length === 0 && result.highEntropy.length === 0) {
      return;
    }

    console.log(`📁 File: ${result.file}`);
    console.log('-'.repeat(80));

    if (result.secrets.length > 0) {
      console.log(`  ⚠️  Found ${result.secrets.length} potential secret(s):`);
      result.secrets.forEach((secret, i) => {
        console.log(`    ${i + 1}. Line ${secret.line}:${secret.column}`);
        console.log(`       Type: ${secret.type}`);
        console.log(`       Match: ${secret.match.substring(0, 50)}${secret.match.length > 50 ? '...' : ''}`);
        totalSecrets++;
      });
    }

    if (result.highEntropy.length > 0) {
      console.log(`  🔒 Found ${result.highEntropy.length} high-entropy string(s):`);
      result.highEntropy.forEach((str, i) => {
        console.log(`    ${i + 1}. Entropy: ${str.entropy}`);
        console.log(`       String: ${str.trunc}`);
        totalHighEntropy++;
      });
    }

    console.log();
  });

  console.log('='.repeat(80));
  console.log('📊 SUMMARY');
  console.log('='.repeat(80));
  console.log(`Files scanned: ${results.length}`);
  console.log(`Potential secrets found: ${totalSecrets}`);
  console.log(`High-entropy strings found: ${totalHighEntropy}`);

  if (totalSecrets > 0 || totalHighEntropy > 0) {
    console.log('\n⚠️  ACTION REQUIRED: Review and remediate the findings above.');
    console.log('   - Move secrets to a secrets manager');
    console.log('   - Ensure .env files are in .gitignore');
    console.log('   - Rotate any exposed credentials');
  } else {
    console.log('\n✅ No secrets detected.');
  }

  console.log('='.repeat(80) + '\n');
}

// Run audit
const rootDir = process.argv[2] || '.';
console.log(`Starting secrets audit in: ${rootDir}`);
const results = scanDirectory(rootDir);
generateReport(results);

// Exit with error code if secrets found
if (results.some(r => r.secrets.length > 0 || r.highEntropy.length > 0)) {
  process.exit(1);
}

