/**
 * Secure Configuration Manager
 * Loads secrets from multiple sources with fallback hierarchy
 * 
 * Priority:
 * 1. Environment variables (runtime)
 * 2. Secrets Manager (AWS/GCP/Azure)
 * 3. Encrypted .env file (for local development)
 */

require('dotenv').config();

class ConfigManager {
  constructor() {
    this.isProduction = process.env.NODE_ENV === 'production';
    this.secretsCache = new Map();
  }

  /**
   * Get a configuration value with validation
   * @param {string} key - Configuration key
   * @param {Object} options - Options { required, defaultValue, validator }
   */
  get(key, options = {}) {
    const { required = false, defaultValue = null, validator = null } = options;

    // Check cache first
    if (this.secretsCache.has(key)) {
      return this.secretsCache.get(key);
    }

    // Try environment variables
    if (process.env[key]) {
      const value = process.env[key];

      if (validator && !validator(value)) {
        if (required) {
          throw new Error(`Invalid value for ${key}: validation failed`);
        }
        return defaultValue;
      }

      this.secretsCache.set(key, value);
      return value;
    }

    // Return default if not found
    if (defaultValue !== null) {
      this.secretsCache.set(key, defaultValue);
      return defaultValue;
    }

    if (required) {
      throw new Error(`Required configuration key '${key}' is missing`);
    }

    return null;
  }

  /**
   * Get all database configuration
   */
  getDatabaseConfig() {
    const url = this.get('DATABASE_URL', {
      required: this.isProduction,
      validator: (val) => {
        if (!val) return false;
        // Basic validation: should be a valid URL
        try {
          const parsed = new URL(val);
          return ['postgresql:', 'postgres:', 'mongodb:', 'mysql:', 'redis:'].includes(parsed.protocol);
        } catch {
          return false;
        }
      }
    });

    if (!url) {
      return {
        host: this.get('DB_HOST', { defaultValue: 'localhost' }),
        port: this.get('DB_PORT', { defaultValue: 5432, validator: Number }),
        username: this.get('DB_USERNAME', { defaultValue: 'postgres' }),
        password: this.get('DB_PASSWORD', { defaultValue: '' }),
        database: this.get('DB_NAME', { required: true, defaultValue: 'app' })
      };
    }

    return { url };
  }

  /**
   * Get AWS configuration
   */
  getAWSConfig() {
    return {
      accessKeyId: this.get('AWS_ACCESS_KEY_ID', {
        required: this.isProduction,
        validator: (val) => /^AKIA[0-9A-Z]{16}$/.test(val)
      }),
      secretAccessKey: this.get('AWS_SECRET_ACCESS_KEY', {
        required: this.isProduction,
        validator: (val) => val && val.length >= 20
      }),
      region: this.get('AWS_REGION', { defaultValue: 'us-east-1' })
    };
  }

  /**
   * Get API configuration
   */
  getAPIKeys() {
    return {
      anthropic: this.get('ANTHROPIC_API_KEY', {
        required: this.isProduction,
        validator: (val) => val && val.startsWith('sk-ant-')
      }),
      stripe: this.get('STRIPE_SECRET_KEY', {
        required: this.isProduction,
        validator: (val) => val && /^sk_(live|test)_/.test(val)
      })
    };
  }

  /**
   * Get JWT signing configuration
   */
  getJWTConfig() {
    const secret = this.get('JWT_SECRET', {
      required: this.isProduction,
      validator: (val) => val && val.length >= 32
    });

    if (!secret && this.isProduction) {
      throw new Error('JWT_SECRET must be at least 32 characters in production');
    }

    return {
      secret: secret || 'development-only-change-in-production',
      expiresIn: this.get('JWT_EXPIRES_IN', { defaultValue: '1h' }),
      algorithm: 'HS256'
    };
  }

  /**
   * Get application configuration
   */
  getAppConfig() {
    return {
      name: this.get('APP_NAME', { defaultValue: 'MyApp' }),
      version: this.get('APP_VERSION', { defaultValue: '1.0.0' }),
      port: this.get('PORT', { defaultValue: 3000, validator: Number }),
      environment: this.get('NODE_ENV', { defaultValue: 'development' }),
      logLevel: this.get('LOG_LEVEL', { defaultValue: 'info' })
    };
  }

  /**
   * Validate all required configuration
   */
  validate() {
    try {
      const errors = [];

      try { this.getJWTConfig(); } catch (e) { errors.push(`JWT: ${e.message}`); }
      try { this.getDatabaseConfig(); } catch (e) { errors.push(`Database: ${e.message}`); }

      if (errors.length > 0) {
        throw new Error('Configuration validation failed:\n' + errors.join('\n'));
      }

      console.log('✅ Configuration validation passed');
      return true;
    } catch (error) {
      console.error('❌ Configuration error:', error.message);
      if (this.isProduction) {
        throw error;
      }
      return false;
    }
  }

  /**
   * Clear cache (useful for testing or hot reload)
   */
  clearCache() {
    this.secretsCache.clear();
  }

  /**
   * Log configuration (sanitized for security)
   */
  logConfig() {
    const config = {
      app: this.getAppConfig(),
      database: this.getDatabaseConfig().url ? {
        url: '[REDACTED]'
      } : {
        host: this.getDatabaseConfig().host,
        port: this.getDatabaseConfig().port,
        username: this.getDatabaseConfig().username,
        password: '[REDACTED]',
        database: this.getDatabaseConfig().database
      },
      aws: {
        accessKeyId: this.getAWSConfig().accessKeyId ? '[REDACTED]' : undefined,
        region: this.getAWSConfig().region
      },
      apiKeys: {
        anthropic: this.getAPIKeys().anthropic ? '[REDACTED]' : undefined,
        stripe: this.getAPIKeys().stripe ? '[REDACTED]' : undefined
      }
    };

    console.log('Current configuration:');
    console.log(JSON.stringify(config, null, 2));
  }
}

// Export singleton instance
const config = new ConfigManager();

// Validate on load
if (config.isProduction) {
  config.validate();
}

module.exports = config;

/**
 * AWS Secrets Manager Integration
 * 
 * This module provides secure integration with AWS Secrets Manager
 * for managing application secrets at runtime.
 */

import {
  SecretsManagerClient,
  GetSecretValueCommand,
  DescribeSecretCommand,
  RotateSecretCommand,
  CreateSecretCommand,
  UpdateSecretCommand
} from '@aws-sdk/client-secrets-manager';
import { NodeHttpHandler } from '@smithy/node-http-handler';

export interface SecretRotationConfig {
  automaticallyAfterDays: number;
  rotationRules?: {
    AutomaticallyAfterDays: number;
  };
}

export interface SecretMetadata {
  name: string;
  arn?: string;
  version?: string;
  lastAccessed?: Date;
  nextRotation?: Date;
}

export class AWSSecretsManager {
  private client: SecretsManagerClient;
  private cache: Map<string, { value: any; expires: number }>;
  private defaultCacheTTL: number;

  constructor(region: string = process.env.AWS_REGION || 'us-east-1') {
    this.client = new SecretsManagerClient({
      region,
      // Add retry configuration
      maxAttempts: 3,
      // Use HTTPS for all requests
      requestHandler: new NodeHttpHandler({
        connectionTimeout: 3000,
        socketTimeout: 3000
      })
    });

    this.cache = new Map();
    this.defaultCacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  /**
   * Get a secret from AWS Secrets Manager
   * @param secretName - Name/ARN of the secret
   * @param versionId - Optional specific version to retrieve
   * @param stage - Optional version stage (default: AWSCURRENT)
   */
  async getSecret(
    secretName: string,
    versionId?: string,
    stage?: string
  ): Promise<any> {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && cached.expires > Date.now()) {
      console.log(`🔒 Cache hit for secret: ${secretName}`);
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({
        SecretId: secretName,
        VersionId: versionId,
        VersionStage: stage || 'AWSCURRENT'
      });

      console.log(`🔓 Fetching secret: ${secretName} (Cache Miss)`);
      const response = await this.client.send(command);

      let secret: any;

      if (response.SecretString) {
        // Parse JSON string
        try {
          secret = JSON.parse(response.SecretString);
        } catch {
          secret = response.SecretString;
        }
      } else if (response.SecretBinary) {
        // Handle binary secrets
        secret = Buffer.from(response.SecretBinary, 'base64').toString('utf-8');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        expires: Date.now() + this.defaultCacheTTL
      });

      return secret;
    } catch (error: any) {
      console.error(`❌ Failed to retrieve secret '${secretName}':`, error.message);

      if (error.name === 'ResourceNotFoundException') {
        throw new Error(`Secret '${secretName}' not found in AWS Secrets Manager`);
      } else if (error.name === 'AccessDeniedException') {
        throw new Error(`Access denied to secret '${secretName}'. Check IAM permissions.`);
      }

      throw error;
    }
  }

  /**
   * Get multiple secrets in parallel
   */
  async getSecrets(secretNames: string[]): Promise<Map<string, any>> {
    const results = new Map<string, any>();

    await Promise.all(
      secretNames.map(async (name) => {
        try {
          const secret = await this.getSecret(name);
          results.set(name, secret);
        } catch (error: any) {
          console.error(`Failed to get secret ${name}:`, error.message);
          // Collect errors but don't fail the entire operation
          results.set(name, { error: error.message });
        }
      })
    );

    return results;
  }

  /**
   * Create a new secret
   */
  async createSecret(
    name: string,
    secretValue: string | Record<string, any>,
    description?: string,
    tags?: Array<{ Key: string; Value: string }>
  ): Promise<string> {
    const secretString = typeof secretValue === 'string'
      ? secretValue
      : JSON.stringify(secretValue);

    const command = new CreateSecretCommand({
      Name: name,
      SecretString: secretString,
      Description: description,
      Tags: tags
    });

    const response = await this.client.send(command);
    console.log(`✅ Created secret: ${name} (ARN: ${response.ARN})`);

    return response.ARN!;
  }

  /**
   * Update an existing secret
   */
  async updateSecret(
    name: string,
    secretValue: string | Record<string, any>,
    description?: string
  ): Promise<string> {
    const secretString = typeof secretValue === 'string'
      ? secretValue
      : JSON.stringify(secretValue);

    const command = new UpdateSecretCommand({
      SecretId: name,
      SecretString: secretString,
      Description: description
    });

    const response = await this.client.send(command);

    // Invalidate cache
    this.cache.delete(name);

    console.log(`✅ Updated secret: ${name} (Version: ${response.VersionId})`);

    return response.VersionId!;
  }

  /**
   * Get secret metadata (without revealing the secret value)
   */
  async getSecretMetadata(secretName: string): Promise<SecretMetadata> {
    const command = new DescribeSecretCommand({ SecretId: secretName });
    const response = await this.client.send(command);

    return {
      name: response.Name!,
      arn: response.ARN,
      version: response.VersionIdsToStages?.AWSCURRENT?.[0],
      lastAccessed: response.LastAccessedDate,
      nextRotation: response.NextRotationDate
    };
  }

  /**
   * Invalidate cache for a specific secret or all secrets
   */
  invalidateCache(secretName?: string): void {
    if (secretName) {
      this.cache.delete(secretName);
      console.log(`🗑️  Cache invalidated for: ${secretName}`);
    } else {
      this.cache.clear();
      console.log(`🗑️  All cache invalidated`);
    }
  }

  /**
   * Set cache TTL for future requests
   */
  setCacheTTL(ttlMs: number): void {
    this.defaultCacheTTL = ttlMs;
    // Clear existing cache as TTL changed
    this.cache.clear();
  }

  /**
   * Health check for Secrets Manager connectivity
   */
  async healthCheck(): Promise<boolean> {
    try {
      // Try to list secrets (this will fail without proper permissions)
      // We don't actually need to list, just connect
      await this.client.config.credentials();
      return true;
    } catch (error) {
      console.error('Secrets Manager health check failed:', error);
      return false;
    }
  }
}

// Example usage:
//
