const nodeVault = require('node-vault');

class VaultSecretsManager {
  constructor(options = {}) {
    this.vault = nodeVault({
      endpoint: options.endpoint || process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
      token: options.token || process.env.VAULT_TOKEN
    });
    this.cache = new Map();
  }

