```javascript
// 🔒 LAYERED SECRETS APPROACH
require('dotenv').config();
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class LayeredSecretsManager {
  constructor() {
    this.secretsManager = new SecretsManagerClient();
    this.loadedSecrets = new Map();
  }

  async get(key) {
    // Priority 1: In-memory cache (already loaded)
    if (this.loadedSecrets.has(key)) {
      return this.loadedSecrets.get(key);
    }

    // Priority 2: Environment variables (local dev)
    if (process.env[key]) {
      this.loadedSecrets.set(key, process.env[key]);
      return process.env[key];
    }

    // Priority 3: AWS Secrets Manager (production)
    if (process.env.NODE_ENV === 'production') {
      const secretName = this.mapToSecretName(key);
      try {
        const secretValue = await this.loadFromSecretsManager(secretName);
        this.loadedSecrets.set(key, secretValue);
        return secretValue;
      } catch (error) {
        console.error(`Failed to load ${key} from Secrets Manager: ${error.message}`);
      }
    }

    // Priority 4: Throw error - secret not found
    throw new Error(`Required secret "${key}" not found in any source`);
  }

  mapToSecretName(key) {
    const mapping = {
      'DATABASE_URL': 'myapp/prod/database',
      'STRIPE_SECRET_KEY': 'myapp/prod/stripe',
      'AWS_ACCESS_KEY_ID': 'myapp/prod/aws',
      'ANTHROPIC_API_KEY': 'myapp/prod/anthropic',
      'LOGFIRE_TOKEN': 'myapp/prod/logging'
    };
    return mapping[key] || key;
  }

  async loadFromSecretsManager(secretName) {
    const command = new GetSecretValueCommand({
      SecretId: secretName,
      VersionStage: 'AWSCURRENT'
    });

    const response = await this.secretsManager.send(command);

    if (response.SecretString) {
      const parsed = JSON.parse(response.SecretString);
      return parsed.value || parsed.api_key || parsed.connection_string;
    }

    throw new Error('Secret has no value');
  }

  // Load all required secrets at startup
  async loadAll(requiredKeys) {
    for (const key of requiredKeys) {
      await this.get(key);
    }
  }

  // Securely display masked secrets (for debugging)
  debugInfo() {
    const info = {};
    this.loadedSecrets.forEach((value, key) => {
      info[key] = this.maskSecret(value);
    });
    return info;
  }

  maskSecret(value) {
    if (!value) return '[empty]';
    if (value.length <= 8) return '***';
    return value.substring(0, 4) + '...' + value.substring(value.length - 4);
  }
}

