require('dotenv').config(); // Load only for local dev
const express = require('express');

// Production secrets management
async function loadSecrets() {
  if (process.env.NODE_ENV === 'production') {
    const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
    const client = new SecretsManagerClient({ region: process.env.AWS_REGION });

    const requiredSecrets = [
      'myapp/prod/database',
      'myapp/prod/stripe',
      'myapp/prod/jwt'
    ];

    for (const secretName of requiredSecrets) {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await client.send(command);
      const secret = JSON.parse(response.SecretString);

      // Set environment variables from secrets
      if (secretName.includes('database')) process.env.DATABASE_URL = secret.connection_string;
      if (secretName.includes('stripe')) process.env.STRIPE_SECRET_KEY = secret.api_key;
      if (secretName.includes('jwt')) process.env.JWT_SECRET = secret.secret;
    }
  }
}

// Validate required secrets are present
function validateSecrets() {
  const required = ['DATABASE_URL', 'JWT_SECRET'];
  const missing = required.filter(key => !process.env[key]);

  if (missing.length > 0) {
    throw new Error(`Missing required secrets: ${missing.join(', ')}`);
  }
}

