### **Option A: AWS Secrets Manager (Recommended for AWS)**
```javascript
// secrets-manager.js
const AWS = require('aws-sdk');
const client = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

const getSecret = async (secretName) => {
  try {
    const data = await client.getSecretValue({ SecretId: secretName }).promise();

    if ('SecretString' in data) {
      return JSON.parse(data.SecretString);
    }

    // For binary secrets
    return Buffer.from(data.SecretBinary, 'base64').toString('ascii');
  } catch (error) {
    if (error.code === 'DecryptionFailureException') {
      throw new Error('Secrets Manager cannot decrypt the secret');
    }
    throw error;
  }
};

// Cache secrets in memory to avoid excessive API calls
const secretCache = new Map();
const CACHE_TTL = 5 * 60 * 1000; // 5 minutes

const getSecretWithCache = async (secretName) => {
  const cached = secretCache.get(secretName);
  if (cached && Date.now() - cached.timestamp < CACHE_TTL) {
    return cached.value;
  }

  const value = await getSecret(secretName);
  secretCache.set(secretName, { value, timestamp: Date.now() });
  return value;
};

module.exports = { getSecret, getSecretWithCache };
```

