```javascript
// secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({
  region: process.env.AWS_REGION || 'us-east-1'
});

async function getSecret(secretName) {
  try {
    const response = await client.send(
      new GetSecretValueCommand({ SecretId: secretName })
    );

    if (response.SecretString) {
      return JSON.parse(response.SecretString);
    }

    // Handle binary secrets
    if (response.SecretBinary) {
      return Buffer.from(response.SecretBinary, 'base64').toString('utf-8');
    }
  } catch (error) {
    console.error(`Error retrieving secret ${secretName}:`, error);
    throw new Error('Failed to retrieve secrets');
  }
}

// Cache secrets to avoid repeatedly calling Secrets Manager
let secretsCache = null;
let cacheExpiry = null;
const CACHE_TTL = 5 * 60 * 1000; // 5 minutes

async function getSecrets() {
  const now = Date.now();

  if (secretsCache && cacheExpiry && now < cacheExpiry) {
    return secretsCache;
  }

  // Fetch from AWS Secrets Manager
  const secrets = await getSecret('prod/my-app/secrets');
  secretsCache = secrets;
  cacheExpiry = now + CACHE_TTL;

  // Set process.env for compatibility
  Object.assign(process.env, secrets);

  return secrets;
}

module.exports = { getSecrets, getSecret };
