**config/secrets.js**
```javascript
const { validateSecrets } = require('./secrets.validator');
const { loadFromSSM } = require('./secrets.providers/aws-ssm');
const { loadFromEnv } = require('./secrets.providers/env');

class SecretsManager {
  constructor() {
    this.loaded = false;
  }

  async load() {
    const provider = process.env.SECRETS_PROVIDER || 'env';

    switch (provider) {
      case 'aws-ssm':
        await loadFromSSM();
        break;
      case 'vault':
        await loadFromVault();
        break;
      case 'env':
      default:
        await loadFromEnv();
        break;
    }

    // Validate all required secrets are present
    validateSecrets();

    // Redact secrets from environment (optional, for security)
    this.redactSensitiveEnv();

    this.loaded = true;
    console.log('Secrets loaded successfully');
  }

  redactSensitiveEnv() {
    // Keep references but mark for logging redaction
    process.env._REDACTED_SECRETS = [
      'DATABASE_URL',
      'JWT_SECRET',
      'AWS_SECRET_ACCESS_KEY',
      'ANTHROPIC_API_KEY',
      'STRIPE_SECRET_KEY'
    ].join(',');
  }

  get(key) {
    return process.env[key];
  }

  getSafe(key) {
    const value = process.env[key];
    if (!value) return null;

    // Return partially masked value for logging
    if (key.includes('SECRET') || key.includes('KEY') || key.includes('TOKEN')) {
      return `${value.substring(0, 4)}...${value.substring(Math.max(0, value.length - 4))}`;
    }
    return value;
  }
}

module.exports = new SecretsManager();
```

**config/secrets.validator.js**
```javascript
const REQUIRED_SECRETS = {
  DATABASE_URL: 'Database connection string',
  JWT_SECRET: 'JWT signing key (min 32 chars)',
  NODE_ENV: 'Environment (development/production)'
};

const CONDITIONAL_SECRETS = {
  production: [
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'STRIPE_SECRET_KEY'
  ]
};

function validateSecrets() {
  const errors = [];

  // Check required secrets
  Object.entries(REQUIRED_SECRETS).forEach(([key, description]) => {
    if (!process.env[key]) {
      errors.push(`Missing required secret: ${key} (${description})`);
    }
  });

  // Check conditional secrets
  if (process.env.NODE_ENV === 'production') {
    CONDITIONAL_SECRETS.production.forEach(key => {
      if (!process.env[key]) {
        errors.push(`Missing production secret: ${key}`);
      }
    });
  }

  // Validate JWT secret strength
  if (process.env.JWT_SECRET && process.env.JWT_SECRET.length < 32) {
    errors.push('JWT_SECRET must be at least 32 characters');
  }

  if (errors.length > 0) {
    console.error('❌ Secrets validation failed:');
    errors.forEach(error => console.error(`  - ${error}`));
    throw new Error('Secrets validation failed');
  }

  console.log('✅ All secrets validated');
}

module.exports = { validateSecrets };
```

