### 9. **Runtime Secret Validation**

```javascript
// Prevent inadvertent secret leakage in logs
const originalConsoleLog = console.log;
const sensitiveKeys = ['SECRET', 'KEY', 'TOKEN', 'PASSWORD'];

console.log = function(...args) {
  const sanitized = args.map(arg => {
    if (typeof arg === 'string') {
      let sanitized = arg;
      sensitiveKeys.forEach(key => {
        const regex = new RegExp(`${key}=\\S+`, 'gi');
        sanitized = sanitized.replace(regex, `${key}=***REDACTED***`);
      });
      return sanitized;
    }
    return arg;
  });
  originalConsoleLog.apply(console, sanitized);
};
```

