```javascript
// ✅ config/secrets.js - AWS Secrets Manager integration
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const secretsManager = new SecretsManagerClient({
  region: process.env.AWS_REGION || 'us-east-1'
});

const secretsCache = new Map();

/**
 * Fetch a secret from AWS Secrets Manager with caching
 */
const getSecret = async (secretName, forceRefresh = false) => {
  // Check cache first
  if (!forceRefresh && secretsCache.has(secretName)) {
    const cached = secretsCache.get(secretName);
    // Cache expires after 5 minutes
    if (Date.now() - cached.timestamp < 300000) {
      return cached.value;
    }
  }

  try {
    const command = new GetSecretValueCommand({ SecretId: secretName });
    const response = await secretsManager.send(command);

    const secretValue = response.SecretString 
      ? JSON.parse(response.SecretString) 
      : response.SecretBinary;

    // Cache the secret
    secretsCache.set(secretName, {
      value: secretValue,
      timestamp: Date.now()
    });

    return secretValue;
  } catch (error) {
    if (error.name === 'ResourceNotFoundException') {
      throw new Error(`Secret "${secretName}" not found`);
    }
    throw new Error(`Failed to fetch secret "${secretName}": ${error.message}`);
  }
};

/**
 * Initialize all required secrets on startup
 */
const initializeSecrets = async () => {
  const secretNames = [
    'prod/app/database',
    'prod/app/aws-credentials',
    'prod/app/stripe',
    'prod/app/anthropic-api'
  ];

  console.log('🔐 Loading secrets from AWS Secrets Manager...');

  const secrets = {};
  for (const name of secretNames) {
    try {
      secrets[name] = await getSecret(name);
      console.log(`✅ Loaded: ${name}`);
    } catch (error) {
      console.error(`❌ Failed to load ${name}:`, error.message);
      if (process.env.NODE_ENV === 'production') {
        process.exit(1);
      }
    }
  }

  return secrets;
};

module.exports = { initializeSecrets, getSecret };
