    const errors = [];

    // Production doesn't allow CANARY values
    if (this.env.nodeEnv === 'production') {
      Object.entries(this.env).forEach(([key, value]) => {
        if (typeof value === 'string' && value.includes('CANARY')) {
          errors.push(`${key} contains placeholder CANARY value`);
        }
        if (typeof value === 'object') {
