  }

  isDevelopment() {
    return this.env.nodeEnv === 'development';
  }

  isProduction() {
    return this.env.nodeEnv === 'production';
  }
}

module.exports = new Config();
```

**Usage:**
```javascript
const config = require('./config');

console.log(config.get('database.url')); // Get nested value
console.log(config.isProduction()); // Check environment
```

