## 🛡️ Secrets Security Best Practices

### 1. **Never Commit Secrets**
```bash
# Check if secrets were ever committed
git log --all --full-history --source -- "*.env*" "*.key" "*.pem"
```

### 2. **Rotate Compromised Secrets**
```javascript
// AWS SDK example for secret rotation
const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager();

async function rotateSecret(secretId) {
  try {
    await secretsManager.rotateSecret({
      SecretId: secretId,
      RotationLambdaARN: process.env.ROTATION_LAMBDA_ARN
    }).promise();

    console.log(`✅ Secret ${secretId} rotation initiated`);
  } catch (error) {
    console.error(`❌ Failed to rotate ${secretId}:`, error);
    throw error;
  }
}
```

### 3. **Detect Canary Token Usage**
```javascript
function detectCanaryTokens(obj, path = '') {
  const issues = [];

  for (const [key, value] of Object.entries(obj)) {
    const fullPath = path ? `${path}.${key}` : key;

    if (typeof value === 'string' && value.includes('CANARY')) {
      issues.push({
        path: fullPath,
        value: value.substring(0, 20) + '...',
        severity: 'HIGH'
      });
    } else if (typeof value === 'object' && value !== null) {
      issues.push(...detectCanaryTokens(value, fullPath));
    }
  }

  return issues;
}

// On startup
const canaryIssues = detectCanaryTokens(process.env);
if (canaryIssues.length > 0) {
  if (process.env.NODE_ENV === 'production') {
    throw new Error(
      `🚨 PRODUCTION USAGE OF CANARY TOKENS DETECTED:\n` +
      canaryIssues.map(i => `  - ${i.path}`).join('\n')
    );
  } else {
    console.warn(
      `⚠️  Development mode - CANARY tokens in use:\n` +
      canaryIssues.map(i => `  - ${i.path}`).join('\n')
    );
  }
}
```

### 4. **Secure File Permissions**
```javascript
const fs = require('fs');
const { resolve } = require('path');

function checkEnvFilePermissions() {
  const envFiles = ['.env', '.env.local', '.env.production'];

  envFiles.forEach(file => {
    try {
      const stats = fs.statSync(file);
      const mode = (stats.mode & parseInt('777', 8)).toString(8);

      if (mode !== '600') {
        console.warn(
          `⚠️  Insecure permissions on ${file}: ${mode} (should be 600)\n` +
          `   Run: chmod 600 ${file}`
        );
      }
    } catch (error) {
      // File doesn't exist, that's ok
    }
  });
}

checkEnvFilePermissions();
```

